        # Pestaña Acceso móvil
        mobile_access_tab = ttk.Frame(notebook)
        notebook.add(mobile_access_tab, text="Acceso móvil")
        def build_mobile_access():
            for child in mobile_access_tab.winfo_children():
                child.destroy()
